//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_prev`; the
//! native twin is `benches/native/Bench/StringWalkPrevAscii.lean`.
//! one iteration is a whole walk: p = prev(s, p) from a chunk end to 0, over 896 bytes of ascii
//! text

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &String, n: u64) -> u64 {
    let s = inp.as_bytes();
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut p = nat_box(s.len() as u64 - 14 * (x & 7));
            let mut k = 0u64;
            while nat_unbox(p) != 0 {
                p = nat_box(string::utf8_prev(s, nat_unbox(p)));
                k += 1;
            }
            k
        });
    }
    acc
}

fn main() {
    run(|| ascii(), kernel)
}
